ALTER TABLE public.crm_propostas ADD COLUMN arquivo_path text, ADD COLUMN arquivo_origem_path text, ADD COLUMN importada boolean NOT NULL DEFAULT false, ADD COLUMN legado jsonb, ADD COLUMN lista_preco_id uuid REFERENCES public.crm_listas_preco(id), ADD COLUMN template_codigo text, ADD COLUMN tipo_venda text;
ALTER TABLE public.crm_proposta_itens ADD COLUMN modo text NOT NULL DEFAULT 'fornecimento' CHECK(modo IN ('fornecimento','realocacao')), ADD COLUMN nota_interna text, ADD COLUMN categoria_ponto text, ADD COLUMN origem_faixa text, ADD COLUMN composicao boolean NOT NULL DEFAULT false, ADD COLUMN nome_proposta text, ADD COLUMN regra_medicao_id uuid REFERENCES public.crm_regras_medicao(id), ADD COLUMN regra_medicao_desc text, ADD COLUMN preco_ponto_id uuid REFERENCES public.crm_precos_ponto(id), ADD COLUMN preco_tabela_setup numeric(12,2), ADD COLUMN preco_tabela_mensal numeric(12,2), ADD COLUMN produto_nome text, ADD COLUMN produto_texto_tecnico text;
ALTER TABLE public.crm_proposta_pendencias ADD COLUMN tipo text, ADD COLUMN origem text, ADD COLUMN valor_parcial numeric(14,2), ADD COLUMN linha integer, ADD COLUMN item_id uuid REFERENCES public.crm_proposta_itens(id);
ALTER TABLE public.crm_lotes_custo ADD COLUMN observacoes text;
ALTER TABLE public.crm_custo_base_produto ADD COLUMN custo_base numeric(12,2), ADD COLUMN observacoes text, ADD COLUMN created_at timestamptz DEFAULT now(), ADD COLUMN origem_custo text, ADD COLUMN updated_at timestamptz DEFAULT now(), ADD COLUMN custo_mensal numeric(12,2), ADD COLUMN valores_originais jsonb;
ALTER TABLE public.crm_tabela_precos ADD COLUMN lista_id uuid REFERENCES public.crm_listas_preco(id), ADD COLUMN notas_internas text, ADD COLUMN produto_codigo text REFERENCES public.crm_produtos_myio(codigo), ADD COLUMN insumo_id uuid REFERENCES public.crm_insumos(id), ADD COLUMN servico_codigo text REFERENCES public.crm_servicos_instalacao(codigo), ADD COLUMN valores_originais jsonb;
ALTER TABLE public.crm_tabela_precos_custo ADD COLUMN custo_origem text;
ALTER TABLE public.crm_proposta_memoria ADD COLUMN historico_original jsonb;
CREATE TABLE public.crm_documentos_migrados(path text PRIMARY KEY,storage_path text NOT NULL UNIQUE,file_name text NOT NULL,file_size bigint NOT NULL,sha256 text NOT NULL,grupo text NOT NULL,internal_only boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.crm_documentos_migrados TO authenticated; GRANT ALL ON public.crm_documentos_migrados TO service_role; ALTER TABLE public.crm_documentos_migrados ENABLE ROW LEVEL SECURITY; CREATE POLICY crm_documentos_read ON public.crm_documentos_migrados FOR SELECT TO authenticated USING(private.has_app_access(auth.uid(),'crm') AND (NOT internal_only OR public.is_erp_admin(auth.uid())));
COMMENT ON TABLE public.crm_perfis_legado IS 'Historical identities only; papel and visao_geral never grant ERP privileges.';
COMMENT ON COLUMN public.crm_tabela_precos.valores_originais IS 'Imported nullable prices retained without treating an unknown price as zero.';
COMMENT ON COLUMN public.crm_custo_base_produto.valores_originais IS 'Imported nullable component values retained independently of current operational defaults.';